\label{varareaform}
If $f\colon S^2\to(M,g(t_0))$ is a branched minimal sphere, then
\[
\left.\frac d{dt}\Area_{g(t)}f(S^2)\right|_{t=t_0}
\le -4\pi-\frac12R_{\min}(g(t_0))\Area_{g(t_0)}f(S^2).
\]
\end{claim}
